{
  "claims": [
    {
      "claim": "The bill would change financial-aid eligibility requirements in Tennessee Code Annotated, Section 49-4-930(c)(2)(A).",
      "summary_quote": "This bill would change the eligibility requirements for financial aid under Tennessee Code Annotated, Section 49-4-930(c)(2)(A).",
      "verdict": "supported",
      "source_quote": "SECTION 1. Tennessee Code Annotated, Section 49-4-930(c)(2)(A), is amended by\n\ndeleting the subdivision and substituting:\n\n (A) Is a sophomore, junior, or senior in high school; or",
      "error_type": "none",
      "rationale": "The bill replaces the specified subdivision with a high-school grade-level criterion in an act concerning financial aid."
    },
    {
      "claim": "Being a sophomore, junior, or senior in high school would be sufficient to make a person eligible for financial aid.",
      "summary_quote": "Under this proposal, a person would be eligible if they are a sophomore, junior, or senior in high school.",
      "verdict": "not_established",
      "source_quote": "(A) Is a sophomore, junior, or senior in high school; or",
      "error_type": "condition_exception",
      "rationale": "The bill establishes a grade-level criterion within one subdivision, not a complete eligibility rule. The surrounding requirements are not reproduced, so the text does not establish that this criterion alone makes a person eligible."
    },
    {
      "claim": "If enacted, the changes would take effect July 1, 2025.",
      "summary_quote": "If passed, these changes would take effect on July 1, 2025.",
      "verdict": "supported",
      "source_quote": "SECTION 2. This act takes effect July 1, 2025, the public welfare requiring it.",
      "error_type": "none",
      "rationale": "Section 2 expressly supplies the stated effective date."
    }
  ]
}
